// Regenerate frontend/demo-job.json — the worked sample job a new account
// opens before it has drawn anything.
//
//   node floodroofing/tools/make-demo-job.mjs
//
// Build the sample job that ships with the app. It is generated by DRIVING the
// real app — draw, calibrate, spec, price — so it is a genuine job snapshot
// rather than a hand-written fixture that would rot the first time the schema
// moved. Re-run this after any change to snapshotCurrentJob().
import { chromium } from 'playwright';
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'frontend');
const b = await chromium.launch();
const ctx = await b.newContext({ viewport:{width:1500,height:1000} });
const pg = await ctx.newPage();
pg.on('pageerror', e => console.log('PAGEERROR', e.message));
pg.on('dialog', d => d.accept());
await pg.route('**/flood-roofing-estimator-production.up.railway.app/**',
  r => r.fulfill({status:200,contentType:'application/json',body:'[]'}));
await pg.addInitScript(() => {
  localStorage.setItem('fr_token','t');
  localStorage.setItem('fr_settings','null');
  localStorage.setItem('fr_user', JSON.stringify({ email:'you@example.co.nz', name:'You' }));
});
await pg.goto('file://' + join(DIR, 'index.html'));
await pg.waitForTimeout(3000);
await pg.evaluate(() => { const w=document.getElementById('setupWizard'); if(w) w.remove(); });

// ── 1. the roof ──
const geo = await pg.evaluate(() => {
  gotoTab('roof');
  clearAll(true); setTool('outline');
  // An L-shaped hip-and-valley house: two ridges, a valley, four hips and a
  // barge — enough that the cut list and the flashing schedule have something
  // to show, and a shape a roofer recognises.
  DRAW.currentPts = [[120,140],[620,140],[620,420],[430,420],[430,700],[120,700]];
  finishCurrent();
  DRAW.scaleMetresPerPx = 0.0265;
  autoGenerateRoof('hip');
  if (DRAW.roofs && DRAW.roofs[0]) DRAW.roofs[0].name = 'Main Roof';
  try { _syncCurrentToRoof(); } catch(e){}
  return { lines: DRAW.lines.length, types: Array.from(new Set(DRAW.lines.map(l=>l.type))) };
});
console.log('1. geometry —', JSON.stringify(geo));

// ── 2. the job details and the spec ──
await pg.evaluate(() => {
  const set = (id, v) => { const el = document.getElementById(id); if (el){ el.value = v;
    el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); } };
  set('jobClient','M. & R. Whitiora');
  set('jobAddr','24 Kauri Road, Kerikeri');
  set('jobEmail','sample@roofmap.co.nz');
  set('jobPhone','021 555 0134');
  set('jobNo','SAMPLE');
  set('matProfile','Corrugate');
  set('matGrade','Colorsteel Maxam');
  set('matThickness','0.40g');
  set('matColour','Ironsand');
  set('matRidgeType','standard');
  set('matGutter','colorsteel-box');
});
await pg.waitForTimeout(500);

// ── 3. price it, the way the office would ──
const priced = await pg.evaluate(async () => {
  gotoTab('materials');
  await new Promise(r => setTimeout(r, 1400));
  gotoTab('quote');
  await new Promise(r => setTimeout(r, 1400));
  try { _openPricingPanel(true); } catch(e){}
  await new Promise(r => setTimeout(r, 900));
  // Pick the job type, which is what fills the scope list and therefore the
  // labour hours — the same first click the office makes.
  try { setMainScope('reroof'); } catch(e){ return { err:'scope '+e.message }; }
  await new Promise(r => setTimeout(r, 700));
  try { populateMaterialsFromLines(); } catch(e){ return { err:'materials '+e.message }; }
  try { renderMaterialPriceTable(); } catch(e){}
  try { calcLabour(); } catch(e){ return { err:'labour '+e.message }; }
  try { _autoSyncFromScope(); } catch(e){}
  try { _autoSyncLabourMaterials(); } catch(e){}
  try { buildQuote(); } catch(e){ return { err:'quote '+e.message }; }
  await new Promise(r => setTimeout(r, 900));
  const q = S.quote || {};
  return { lineItems: (q.lineItems||[]).map(l => (l.desc||l.label||'?')+' $'+(l.amount||l.price||0)),
           base: (typeof _qpBaseSub==='function') ? _qpBaseSub() : null,
           labour: S.labour, labourHours: S.labourHours, materials: S.materials,
           scope: (q.scope||'').slice(0,60) };
});
console.log('2. priced —', JSON.stringify(priced));

// ── 4. the snapshot, exactly as a save would write it ──
const snap = await pg.evaluate(() => {
  const s = snapshotCurrentJob();
  // A sample job carries no photos and no aerial image: they'd be megabytes,
  // and they'd be somebody else's house.
  if (s.state){ s.state.photos = []; s.state.img64 = null; s.state.linkedJobId = null;
                s.state.linkedJobNo = null; s.state.linkedJobName = null;
                s.state.fergusSent = null; s.state.orderSent = null; }
  return s;
});
const payload = {
  client_name: 'M. & R. Whitiora',
  site_address: '24 Kauri Road, Kerikeri',
  draw_state: snap,
};
const json = JSON.stringify(payload);
console.log('3. snapshot —', Math.round(json.length/1024)+' KB',
  'roofs', snap.draw.roofs.length, 'lines', snap.draw.lines.length,
  'quote lines', ((snap.state.quote||{}).lines||[]).length);
await writeFile(join(DIR, 'demo-job.json'), JSON.stringify(payload, null, 0));
console.log('written to', join(DIR, 'demo-job.json'));

await ctx.close(); await b.close();
